"use client";

import { useState } from "react";
import {
  Card,
  CardHeader,
  CardTitle,
  CardContent,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Select, SelectTrigger, SelectContent, SelectItem, SelectValue } from "@/components/ui/select";

interface Record {
  firstName: string;
  lastName: string;
  phone: string;
  email: string;
  address: string;
  state: string;
  district: string;
  city: string;
  zip: string;
}

export default function RecordsDashboard() {
  const [records, setRecords] = useState<Record[]>([]);
  const [form, setForm] = useState<Record>({
    firstName: "",
    lastName: "",
    phone: "",
    email: "",
    address: "",
    state: "",
    district: "",
    city: "",
    zip: "",
  });

  const handleChange = (field: keyof Record, value: string) => {
    setForm({ ...form, [field]: value });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setRecords([...records, form]);
    setForm({
      firstName: "",
      lastName: "",
      phone: "",
      email: "",
      address: "",
      state: "",
      district: "",
      city: "",
      zip: "",
    });
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-6">
      {/* Left Form */}
      <Card>
        <CardHeader>
          <CardTitle>Add / Edit the single record Here</CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid gap-2">
              <Label>First Name</Label>
              <Input
                value={form.firstName}
                onChange={(e) => handleChange("firstName", e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label>Last Name</Label>
              <Input
                value={form.lastName}
                onChange={(e) => handleChange("lastName", e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label>Phone (Primary)</Label>
              <Input
                value={form.phone}
                onChange={(e) => handleChange("phone", e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label>Email</Label>
              <Input
                value={form.email}
                onChange={(e) => handleChange("email", e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label>Address</Label>
              <Input
                value={form.address}
                onChange={(e) => handleChange("address", e.target.value)}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="grid gap-2">
                <Label>State</Label>
                <Select onValueChange={(val) => handleChange("state", val)}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select State" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="CA">CA</SelectItem>
                    <SelectItem value="TX">TX</SelectItem>
                    <SelectItem value="NY">NY</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="grid gap-2">
                <Label>District</Label>
                <Select onValueChange={(val) => handleChange("district", val)}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select District" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="CA">CA</SelectItem>
                    <SelectItem value="TX">TX</SelectItem>
                    <SelectItem value="NY">NY</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid gap-2">
              <Label>City</Label>
              <Input
                value={form.city}
                onChange={(e) => handleChange("city", e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label>Zip Code</Label>
              <Input
                value={form.zip}
                onChange={(e) => handleChange("zip", e.target.value)}
              />
            </div>

            <div className="flex gap-4 pt-4">
              <Button type="button" variant="outline" className="w-full">
                Cancel
              </Button>
              <Button type="submit" className="w-full">
                Save
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>

      {/* Right Table */}
      <Card>
        <CardHeader>
          <CardTitle>Show the List of records</CardTitle>
        </CardHeader>
        <CardContent>
          {records.length === 0 ? (
            <p className="text-sm text-muted-foreground">No records found.</p>
          ) : (
            <table className="w-full border border-gray-200 text-sm">
              <thead>
                <tr className="bg-gray-100">
                  <th className="border p-2">First Name</th>
                  <th className="border p-2">Last Name</th>
                  <th className="border p-2">Phone</th>
                  <th className="border p-2">Email</th>
                  <th className="border p-2">Address</th>
                  <th className="border p-2">City</th>
                  <th className="border p-2">Zip</th>
                </tr>
              </thead>
              <tbody>
                {records.map((r, i) => (
                  <tr key={i} className="hover:bg-gray-50">
                    <td className="border p-2">{r.firstName}</td>
                    <td className="border p-2">{r.lastName}</td>
                    <td className="border p-2">{r.phone}</td>
                    <td className="border p-2">{r.email}</td>
                    <td className="border p-2">{r.address}</td>
                    <td className="border p-2">{r.city}</td>
                    <td className="border p-2">{r.zip}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </CardContent>
      </Card>
    </div>
  );
}
